import { getCurrentWorkShiftId } from '~/composables/mobile/shift/useMobileShift';

export default defineNuxtRouteMiddleware(async (to) => {
  const activeId = await getCurrentWorkShiftId();

  if (to.name === 'shift') {
    // On shift selection page: redirect to active shift if one exists
    if (activeId) {
      return navigateTo({ name: 'shift-id', params: { id: activeId } }, { replace: true });
    }
  } else if (to.name === 'shift-id') {
    // On active shift page: redirect to selection if this isn't the active shift
    const routeId = (to.params as { id: string }).id;
    if (activeId !== routeId) {
      return navigateTo({ name: 'shift' }, { replace: true });
    }
  }
});
